package main

// Boundary audit — ported from tools/audit-boundary.mjs.
//
// Categorizes every file in the repo as PROGRAMMATIC (regenerated by tools on
// `make build`) vs TOOL SOURCE (hand-written code that owns those outputs) vs
// HAND-AUTHORED (LLM/human content that no script owns), and surfaces the
// explicit LLM PATCH POINTS inside tool source.
//
//	pipeline audit-boundary            human-readable report; exit 0 always
//	pipeline audit-boundary --strict   JSON to stdout, exit 1 on drift
//	pipeline audit-boundary discover   new files + a suggested pattern for each
//
// The path patterns ARE the source of truth — each one documents which tool
// owns the output and what it generates from. To extend, add a pattern below
// with the owning tool and source reference.
//
// Patterns are matched first-match-wins and the order is load-bearing: a
// catch-all placed before a specific rule shadows it. That is a real bug this
// file already carried once (a dist/components RTL file was attributed to the
// emitter instead of build-rtl), so the ordering is asserted by a test rather
// than left to reading.

import (
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"sync"
)

// A classification pattern. Exactly one of tool/note/owner is set, matching
// the three kinds.
type boundaryPattern struct {
	re     *regexp.Regexp
	match  func(string) bool // used when the rule is not a plain regex
	tool   string            // programmatic: what regenerates it
	source string            // programmatic: what it is generated from
	note   string            // tool-source: what this code owns
	owner  string            // hand-authored: who maintains it
}

func (p boundaryPattern) test(path string) bool {
	if p.match != nil {
		return p.match(path)
	}
	return p.re.MatchString(path)
}

func re(s string) *regexp.Regexp { return regexp.MustCompile(s) }

// hasPrefixAnd is the common shape: a directory prefix plus a suffix test.
func prefixSuffix(prefix string, suffixes ...string) func(string) bool {
	return func(p string) bool {
		if !strings.HasPrefix(p, prefix) {
			return false
		}
		if len(suffixes) == 0 {
			return true
		}
		for _, s := range suffixes {
			if strings.HasSuffix(p, s) {
				return true
			}
		}
		return false
	}
}

func oneOf(paths ...string) func(string) bool {
	set := map[string]bool{}
	for _, p := range paths {
		set[p] = true
	}
	return func(p string) bool { return set[p] }
}

