// ---------------------------------------------------------------- scan

type classification struct {
	Path   string
	Kind   string // programmatic | tool-source | hand-authored | unknown
	Tool   string
	Source string
	Note   string
	Owner  string
}

// label is the grouping key for a classification: the tool that owns it, the
// note describing it, or its owner.
func (c classification) label() string {
	switch {
	case c.Tool != "":
		return c.Tool
	case c.Note != "":
		return c.Note
	case c.Owner != "":
		return c.Owner
	}
	return ""
}

func classifyPath(path string) classification {
	for _, p := range programmaticPatterns {
		if p.test(path) {
			return classification{Path: path, Kind: "programmatic", Tool: p.tool, Source: p.source}
		}
	}
	for _, p := range toolSourcePatterns {
		if p.test(path) {
			return classification{Path: path, Kind: "tool-source", Note: p.note}
		}
	}
	for _, p := range handAuthoredPatterns {
		if p.test(path) {
			return classification{Path: path, Kind: "hand-authored", Owner: p.owner}
		}
	}
	return classification{Path: path, Kind: "unknown"}
}

// auditSkip: dist/ is deliberately NOT skipped — dist/components/*.html is
// git-tracked and is the live library output. tools/contracts/out IS skipped:
// those are runtime oracle artifacts, not repo source.
var auditSkip = []string{".git", "node_modules", ".upstream", "tools/contracts/out"}

func auditWalk(root string) ([]string, error) {
	var out []string
	err := filepath.WalkDir(root, func(p string, d os.DirEntry, err error) error {
		if err != nil {
			return nil // an unreadable directory is skipped, as readdirSync's catch did
		}
		rel, rerr := filepath.Rel(root, p)
		if rerr != nil || rel == "." {
			return nil
		}
		if auditShouldSkip(rel) {
			if d.IsDir() {
				return filepath.SkipDir
			}
			return nil
		}
		if !d.IsDir() {
			out = append(out, rel)
		}
		return nil
	})
	sort.Strings(out)
	return out, err
}

func auditShouldSkip(rel string) bool {
	for _, s := range auditSkip {
		if strings.Contains(s, "/") {
			// path-prefix match
			if rel == s || strings.HasPrefix(rel, s+"/") {
				return true
			}
			continue
		}
		for _, seg := range strings.Split(rel, "/") {
			if seg == s {
				return true
			}
		}
	}
	return false
}

// ------------------------------------------------------- drift detection

// detectDrift finds tool-generated files MODIFIED relative to HEAD. Untracked
// files are NOT drift: they are the normal state after `make build`. Only a
// file someone touched after the tool generated it counts.
func detectDrift(root string, programmatic []classification) []classification {
	modified := gitPaths(root, "--untracked-files=no", func(x, y byte) bool {
		return x == 'M' || y == 'M' || x == 'D' || y == 'D'
	})
	var out []classification
	for _, c := range programmatic {
		if modified[c.Path] {
			out = append(out, c)
		}
	}
	return out
}

// gitPaths runs git status --porcelain and returns the paths whose XY status
// satisfies keep. A git that is not available yields nothing, as the JS did.
func gitPaths(root, untracked string, keep func(x, y byte) bool) map[string]bool {
	out := map[string]bool{}
	cmd := exec.Command("git", "status", "--porcelain", untracked)
	cmd.Dir = root
	b, err := cmd.Output()
	if err != nil {
		return out
	}
	for _, line := range strings.Split(string(b), "\n") {
		if len(line) < 4 {
			continue
		}
		if !keep(line[0], line[1]) {
			continue
		}
		rest := line[3:]
		if i := strings.Index(rest, " -> "); i >= 0 {
			rest = rest[i+4:] // a rename reports the destination
		}
		out[strings.Trim(rest, `"`)] = true
	}
	return out
}

// detectNewFiles lists untracked and staged-added paths — everything new
// since HEAD.
func detectNewFiles(root string) []string {
	paths := gitPaths(root, "--untracked-files=all", func(x, y byte) bool {
		return (x == '?' && y == '?') || x == 'A'
	})
	var out []string
	for p := range paths {
		if strings.HasSuffix(p, "/") {
			continue // git lists directories with a trailing slash
		}
		out = append(out, p)
	}
	sort.Strings(out)
	return out
}

