type suggestion struct {
	Method     string
	Confidence float64
	Kind       string
	Tool       string
	Source     string
	Note       string
	Owner      string
	Sampled    int
	Total      int
}

// suggestFromSiblings looks at files in the SAME DIRECTORY (not the whole
// subtree — that would overweight huge dirs like docs/site/) that already
// match a pattern, and proposes the dominant category.
func suggestFromSiblings(newPath string, all []string, byPath map[string]classification) *suggestion {
	dir := parentDir(newPath)
	var siblings, matched []classification
	for _, p := range all {
		if p == newPath || parentDir(p) != dir {
			continue
		}
		c := byPath[p]
		siblings = append(siblings, c)
		if c.Kind != "" && c.Kind != "unknown" {
			matched = append(matched, c)
		}
	}
	if len(matched) == 0 {
		return nil
	}
	type key struct{ kind, label string }
	counts := map[key]int{}
	for _, m := range matched {
		counts[key{m.Kind, m.label()}]++
	}
	// deterministic winner: highest count, then lexical
	var best key
	bestN := -1
	var keys []key
	for k := range counts {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool {
		if keys[i].kind != keys[j].kind {
			return keys[i].kind < keys[j].kind
		}
		return keys[i].label < keys[j].label
	})
	for _, k := range keys {
		if counts[k] > bestN {
			best, bestN = k, counts[k]
		}
	}
	s := &suggestion{
		Method: "sibling", Kind: best.kind,
		Confidence: float64(bestN) / float64(len(siblings)),
		Sampled:    len(matched), Total: len(siblings),
	}
	switch best.kind {
	case "programmatic":
		s.Tool = best.label
	case "tool-source":
		s.Note = best.label
	case "hand-authored":
		s.Owner = best.label
	}
	return s
}

func parentDir(p string) string {
	if i := strings.LastIndex(p, "/"); i >= 0 {
		return p[:i+1]
	}
	return ""
}

func suggestFromHeuristics(newPath string) *suggestion {
	for _, h := range heuristicHints {
		if h.re.MatchString(newPath) {
			return &suggestion{Method: "heuristic", Confidence: 0.8, Kind: h.kind,
				Tool: h.tool, Source: h.source, Note: h.note, Owner: h.owner}
		}
	}
	return nil
}

func runDiscoverMode(root string, all []string, byPath map[string]classification) {
	newFiles := detectNewFiles(root)
	if len(newFiles) == 0 {
		fmt.Println("No new files detected in git working tree.")
		return
	}
	fmt.Printf("Discovered %d new file%s (untracked + added since HEAD):\n\n",
		len(newFiles), plural(len(newFiles)))
	var matched []classification
	var unmatched []string
	for _, p := range newFiles {
		if c, ok := byPath[p]; ok && c.Kind != "unknown" {
			matched = append(matched, c)
			continue
		}
		unmatched = append(unmatched, p)
	}
	if len(matched) > 0 {
		fmt.Println("ALREADY CLASSIFIED (matches existing pattern)")
		fmt.Println(strings.Repeat("-", 72))
		for _, m := range matched {
			fmt.Printf("  [%s] %s\n", m.Kind, m.Path)
		}
		fmt.Println()
	}
	if len(unmatched) == 0 {
		return
	}
	fmt.Println("UNCLASSIFIED (needs a new pattern)")
	fmt.Println(strings.Repeat("-", 72))
	type row struct {
		path             string
		sibling, heurist *suggestion
	}
	var rows []row
	for _, p := range unmatched {
		rows = append(rows, row{p, suggestFromSiblings(p, all, byPath), suggestFromHeuristics(p)})
	}
	for _, r := range rows {
		fmt.Printf("  %s\n", r.path)
		if s := r.sibling; s != nil {
			fmt.Printf("    sibling-based: %d%% confidence (%d siblings match)\n",
				int(s.Confidence*100+0.5), s.Sampled)
			fmt.Printf("      kind:  %s\n", s.Kind)
			printIf("      tool:  %s\n", s.Tool)
			printIf("      note:  %s\n", s.Note)
			printIf("      owner: %s\n", s.Owner)
		}
		if s := r.heurist; s != nil {
			fmt.Printf("    heuristic: %d%% confidence\n", int(s.Confidence*100+0.5))
			fmt.Printf("      kind:  %s\n", s.Kind)
			printIf("      tool:  %s\n", s.Tool)
			printIf("      source: %s\n", s.Source)
			printIf("      note:  %s\n", s.Note)
			printIf("      owner: %s\n", s.Owner)
		}
		if r.sibling == nil && r.heurist == nil {
			fmt.Println("    NO SUGGESTION — needs manual categorization")
		}
		fmt.Println()
	}
	fmt.Println("SUGGESTED PATTERN ADDITIONS (copy-paste into pipeline/audit_boundary.go):")
	fmt.Println(strings.Repeat("-", 72))
	for _, r := range rows {
		use := r.heurist
		if use == nil {
			use = r.sibling
		}
		if use == nil {
			continue
		}
		switch {
		case use.Tool != "":
			fmt.Printf("  {match: func(p string) bool { /* %s */ }, tool: %q, source: %q},\n",
				r.path, use.Tool, use.Source)
		case use.Note != "":
			fmt.Printf("  {match: func(p string) bool { /* %s */ }, note: %q},\n", r.path, use.Note)
		default:
			fmt.Printf("  {match: func(p string) bool { /* %s */ }, owner: %q},\n", r.path, use.Owner)
		}
	}
}

func printIf(format, v string) {
	if v != "" {
		fmt.Printf(format, v)
	}
}

func plural(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

// ---------------------------------------------------------------- output

// group preserves first-appearance order, which is what makes the report
// stable between runs (a Go map would reshuffle the sections).
type group struct {
	order []string
	items map[string][]string
}

func groupBy(cs []classification, key func(classification) string) *group {
	g := &group{items: map[string][]string{}}
	for _, c := range cs {
		k := key(c)
		if _, seen := g.items[k]; !seen {
			g.order = append(g.order, k)
		}
		g.items[k] = append(g.items[k], c.Path)
	}
	return g
}

func (g *group) print() {
	for _, k := range g.order {
		paths := g.items[k]
		fmt.Println()
		fmt.Printf("[%s]  (%d file%s)\n", k, len(paths), plural(len(paths)))
		for i, p := range paths {
			if i == 8 {
				fmt.Printf("  …and %d more\n", len(paths)-8)
				break
			}
			fmt.Printf("  %s\n", p)
		}
	}
}

func runAuditBoundary(args []string) int {
	root, err := os.Getwd()
	if err != nil {
		fmt.Fprintln(os.Stderr, "pipeline:", err)
		return 1
	}
	all, err := auditWalk(root)
	if err != nil {
		fmt.Fprintln(os.Stderr, "pipeline:", err)
		return 1
	}
	classified := make([]classification, len(all))
	byPath := make(map[string]classification, len(all))
	for i, p := range all {
		classified[i] = classifyPath(p)
		byPath[p] = classified[i]
	}

	if has(args, "discover") {
		runDiscoverMode(root, all, byPath)
		return 0
	}

	var programmatic, toolSource, handAuthored, unknown []classification
	for _, c := range classified {
		switch c.Kind {
		case "programmatic":
			programmatic = append(programmatic, c)
		case "tool-source":
			toolSource = append(toolSource, c)
		case "hand-authored":
			handAuthored = append(handAuthored, c)
		default:
			unknown = append(unknown, c)
		}
	}
	drift := detectDrift(root, programmatic)

	if has(args, "--strict") {
		type driftRow struct {
			Path string `json:"path"`
			Tool string `json:"tool"`
		}
		rows := []driftRow{}
		for _, d := range drift {
			rows = append(rows, driftRow{d.Path, d.Tool})
		}
		out, _ := json.MarshalIndent(struct {
			Programmatic   int        `json:"programmatic"`
			ToolSource     int        `json:"tool_source"`
			HandAuthored   int        `json:"hand_authored"`
			Unknown        int        `json:"unknown"`
			LLMPatchPoints int        `json:"llm_patch_points"`
			Drift          []driftRow `json:"drift"`
		}{len(programmatic), len(toolSource), len(handAuthored), len(unknown),
			len(llmPatchPoints), rows}, "", "  ")
		fmt.Println(string(out))
		if len(drift) == 0 {
			return 0
		}
		return 1
	}

	fmt.Println("PROGRAMMATIC ZONE — regenerated by tools on `make build`")
	fmt.Println(strings.Repeat("=", 72))
	byTool := groupBy(programmatic, func(c classification) string {
		if c.Tool == "" {
			return "(unknown tool)"
		}
		return c.Tool
	})
	byTool.print()
	fmt.Print("\n\n\n\n")
	fmt.Println("HAND-AUTHORED ZONE — LLM/human edits expected, no script owns them")
	fmt.Println(strings.Repeat("=", 72))
	byOwner := groupBy(handAuthored, func(c classification) string {
		if c.Owner == "" {
			return "(unowned)"
		}
		return c.Owner
	})
	byOwner.print()
	fmt.Print("\n\n")
	fmt.Println("TOOL SOURCE — hand-written code that owns the PROGRAMMATIC ZONE")
	fmt.Println(strings.Repeat("=", 72))
	for _, p := range toolSourcePatterns {
		fmt.Println()
		fmt.Printf("[%s]\n", p.note)
		var matches []string
		for _, c := range toolSource {
			if p.test(c.Path) {
				matches = append(matches, c.Path)
			}
		}
		for i, m := range matches {
			if i == 8 {
				fmt.Printf("  …and %d more\n", len(matches)-8)
				break
			}
			fmt.Printf("  %s\n", m)
		}
	}
	fmt.Print("\n\n")
	fmt.Println("LLM PATCH POINTS — explicit hand-coded regions inside tool source")
	fmt.Println(strings.Repeat("=", 72))
	for _, p := range llmPatchPoints {
		fmt.Println()
		loc := p.File
		if p.Lines != "" {
			loc += ":" + p.Lines
		}
		fmt.Printf("[%s]\n", loc)
		fmt.Printf("  %s\n", p.What)
	}
	fmt.Print("\n\n")
	fmt.Println("DRIFT — tool-generated files with uncommitted changes")
	fmt.Println(strings.Repeat("=", 72))
	fmt.Println(`(Tool-generated file is "drift" if git status shows it as`)
	fmt.Println(" modified. NOTE: this is noisy right after `make build` — every")
	fmt.Println(" regenerated file appears as drift until committed. Run")
	fmt.Println(" `git status` to see if drift is from a fresh build vs a")
	fmt.Println(" manual edit. For CI gating, use --strict mode.)")
	switch {
	case len(drift) == 0:
		fmt.Println()
		fmt.Println("(none)")
	case len(drift) > 30:
		fmt.Println()
		fmt.Printf("(%d files — showing first 30; run `git status` for full list)\n", len(drift))
		for _, d := range drift[:30] {
			fmt.Printf("  %s  (%s)\n", d.Path, d.Tool)
		}
	default:
		fmt.Println()
		for _, d := range drift {
			fmt.Printf("  %s  (%s)\n", d.Path, d.Tool)
		}
	}
	fmt.Print("\n\n")
	fmt.Println("SUMMARY")
	fmt.Println(strings.Repeat("=", 72))
	fmt.Printf("  programmatic: %d files (regenerated by %d tools)\n", len(programmatic), len(byTool.order))
	fmt.Printf("  tool source: %d files (hand-written code that owns the PROGRAMMATIC zone)\n", len(toolSource))
	fmt.Printf("  hand-authored: %d files (in %d categories)\n", len(handAuthored), len(byOwner.order))
	fmt.Printf("  unknown: %d files (no pattern matched)\n", len(unknown))
	fmt.Printf("  LLM patch points: %d\n", len(llmPatchPoints))
	fmt.Printf("  drift: %d\n", len(drift))
	if len(unknown) > 0 {
		fmt.Println()
		fmt.Println("UNKNOWN files (no pattern matched — add to programmaticPatterns or handAuthoredPatterns):")
		for i, u := range unknown {
			if i == 20 {
				fmt.Printf("  …and %d more\n", len(unknown)-20)
				break
			}
			fmt.Printf("  %s\n", u.Path)
		}
	}
	return 0
}

// inManifest matches a path a tool recorded as its own output.
//
// The alternative is guessing from the path, and that guess is what made this
// audit report 331 generated files as owned by nobody: docs/demos looked
// hand-authored because most of it once was. A tool that writes a manifest is
// telling you what it owns; reading that is both correct today and correct
// after the tool's coverage changes.
//
// `field` is the key holding the path or the page name — example-oracle
// records {name, out} and example-fixture records {name}. A manifest that
// cannot be read matches nothing, so a missing file degrades to "unknown"
// rather than to a false claim of ownership.
func inManifest(manifest, field string) func(string) bool {
	var mu sync.Mutex
	var owned map[string]bool
	return func(p string) bool {
		mu.Lock()
		defer mu.Unlock()
		if owned == nil {
			// Only a SUCCESSFUL read is remembered. Caching the failure meant
			// one call made before the working directory was the repo root
			// poisoned every later call with an empty set, and every generated
			// page came back unowned.
			//
			// The root is found by walking up rather than taken from the cwd,
			// so this behaves the same whether it runs from the repo root (the
			// audit) or from pipeline/ (go test).
			cwd, err := os.Getwd()
			if err != nil {
				return false
			}
			root, err := findRepoRoot(cwd)
			if err != nil {
				return false
			}
			b, err := os.ReadFile(filepath.Join(root, manifest))
			if err != nil {
				return false
			}
			var rows []map[string]any
			if err := json.Unmarshal(b, &rows); err != nil {
				return false
			}
			m := map[string]bool{}
			for _, r := range rows {
				v, ok := r[field].(string)
				if !ok {
					continue
				}
				// "out" is already a repo path; "name" is a page stem
				if strings.Contains(v, "/") {
					m[v] = true
				} else {
					m["docs/demos/"+v+".html"] = true
				}
			}
			owned = m
		}
		return owned[p]
	}
}
